-- ~/.config/hypr/theme.lua
-- Loads the colors generated by matugen and applies them to the window borders.

local path = os.getenv("HOME") .. "/.config/hypr/matugen-colors.lua"

-- fallback colors, used if matugen has not generated the file yet
local colors = {
  accent   = "rgb(89b4fa)",
  inactive = "rgb(45475a)",
}

-- dofile (not require) so the file is read again on every `hyprctl reload`
local ok, loaded = pcall(dofile, path)
if ok and type(loaded) == "table" then
  colors.accent   = loaded.accent   or colors.accent
  colors.inactive = loaded.inactive or colors.inactive
end

-- plain strings give solid colors (no gradient)
hl.config({
  general = {
    col = {
      active_border   = colors.accent,
      inactive_border = colors.inactive,
    },
  },
})
